def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def segments(row):
        result = []
        c = 0
        while c < w:
            end = c + 1
            while end < w and row[end] == row[c]:
                end += 1
            if row[c] != bg and end - c >= 2:
                result.append((row[c], c, end))
            c = end
        return result

    tops = segments(grid[0])
    bottoms = segments(grid[-1])
    pair = next(((t, b) for t in tops for b in bottoms if t[0] == b[0]), None)
    if pair is None:
        return out

    (bar_color, ts, te), (_, bs, be) = pair
    # The paired bars define the column translation.
    shift = bs - ts
    seeds = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != bar_color
             and not (r == 0 and ts <= c < te)
             and not (r == h - 1 and bs <= c < be)]

    for r, c, color in seeds:
        if ts <= c < te:
            # Draw from the top bar to the marker; transfer a full line to
            # the paired position, stopping at the opposite bar.
            for rr in range(1, r):
                out[rr][c] = color
            out[r][c] = 4
            target = c + shift
            if 0 <= target < w:
                for rr in range(h - 1):
                    out[rr][target] = color
        elif bs <= c < be:
            # Symmetric case: marker is associated with the bottom bar.
            for rr in range(r + 1, h - 1):
                out[rr][c] = color
            out[r][c] = 4
            target = c - shift
            if 0 <= target < w:
                for rr in range(1, h):
                    out[rr][target] = color

    return out
